import type { LatLng } from './geo.ts'
import type { DeviceId, StationId } from './ids.ts'

export type DeviceKind = 'elevator' | 'escalator'

/** Which trips a device serves. Generated by the registry pipeline (Phase 4). */
export type DeviceScope =
  /** Street access or ticket hall: every trip through the station needs it. */
  | { readonly kind: 'station' }
  /** Platforms: trips heading towards any of these terminal stations (one device can serve several). */
  | { readonly kind: 'platform'; readonly towards: readonly StationId[] }
  /** We couldn't tell which platform it serves. Treated as possibly yours. */
  | { readonly kind: 'unknown' }

export interface Device {
  readonly id: DeviceId
  readonly kind: DeviceKind
  readonly scope: DeviceScope
  /** The source's own words for where it goes ("… hacia Boletería"), shown to riders as is. */
  readonly description?: string
  /**
   * The two places it connects, normalised ("boleteria <-> calle"). Two elevators at a station
   * with the same link do the same job, so one backs up the other (ADR 0015).
   */
  readonly link?: string
}

export interface Station {
  readonly id: StationId
  readonly name: string
  readonly location: LatLng
  readonly lines: readonly string[]
  /** Other spellings of the name, e.g. as Google writes it. */
  readonly aliases: readonly string[]
  readonly devices: readonly Device[]
}

export interface Line {
  readonly id: string
  /** The stations trains on this line are signed towards ("dirección X"). */
  readonly terminals: readonly StationId[]
}

export interface Registry {
  readonly stations: readonly Station[]
  readonly lines: readonly Line[]
}
